// ---------- build files: cut files (DXF, mm) and the software ----------
(function(){
var CRCT=(function(){var t=[],c;for(var n=0;n<256;n++){c=n;for(var k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc(u){var c=0xFFFFFFFF;for(var i=0;i<u.length;i++)c=CRCT[(c^u[i])&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0;}
var enc=new TextEncoder(),DT=new Date(),DD=((DT.getFullYear()-1980)<<9)|((DT.getMonth()+1)<<5)|DT.getDate();
function zip(files){var parts=[],cd=[],off=0;
  files.forEach(function(f){var nm=enc.encode(f.name),d=f.data,c=crc(d),h=new DataView(new ArrayBuffer(30));
    h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x0800,true);h.setUint16(12,DD,true);h.setUint32(14,c,true);h.setUint32(18,d.length,true);h.setUint32(22,d.length,true);h.setUint16(26,nm.length,true);
    parts.push(new Uint8Array(h.buffer),nm,d);
    var e=new DataView(new ArrayBuffer(46));e.setUint32(0,0x02014b50,true);e.setUint16(4,20,true);e.setUint16(6,20,true);e.setUint16(8,0x0800,true);e.setUint16(14,DD,true);e.setUint32(16,c,true);e.setUint32(20,d.length,true);e.setUint32(24,d.length,true);e.setUint16(28,nm.length,true);e.setUint32(42,off,true);
    cd.push(new Uint8Array(e.buffer),nm);off+=30+nm.length+d.length;});
  var cdl=cd.reduce(function(a,b){return a+b.length;},0),end=new DataView(new ArrayBuffer(22));
  end.setUint32(0,0x06054b50,true);end.setUint16(8,files.length,true);end.setUint16(10,files.length,true);end.setUint32(12,cdl,true);end.setUint32(16,off,true);
  return new Blob(parts.concat(cd,[new Uint8Array(end.buffer)]),{type:'application/zip'});}
function fx(n){return String(Math.round(n*1000)/1000);}
function DXF(){var o=[];return{
  poly:function(pts,bul){o.push('0','POLYLINE','8','CUT','66','1','10','0','20','0','30','0','70','1');pts.forEach(function(p,i){o.push('0','VERTEX','8','CUT','10',fx(p[0]),'20',fx(p[1]),'30','0');if(bul&&bul[i])o.push('42',String(bul[i]));});o.push('0','SEQEND','8','CUT');return this;},
  rect:function(x,y,w,h){return this.poly([[x,y],[x+w,y],[x+w,y+h],[x,y+h]]);},
  circ:function(x,y,d){o.push('0','CIRCLE','8','CUT','10',fx(x),'20',fx(y),'30','0','40',fx(d/2));return this;},
  bytes:function(){return enc.encode(['0','SECTION','2','HEADER','9','$ACADVER','1','AC1009','9','$INSUNITS','70','4','0','ENDSEC','0','SECTION','2','ENTITIES'].concat(o,['0','ENDSEC','0','EOF']).join('\r\n')+'\r\n');}};}

var SW={"sandtable-software/AGENT-BOX-SETUP.txt": "AGENT BOX SETUP: Raspberry Pi 5, where the agent lives\n\n1. System\n   Raspberry Pi Imager -> Raspberry Pi OS Lite (64-bit) on the microSD card (or an NVMe drive).\n   In the Imager's settings: your own admin user, SSH on. No Wi-Fi.\n\n2. No radio\n   Add to /boot/firmware/config.txt:\n     dtoverlay=disable-wifi\n     dtoverlay=disable-bt\n   Reboot. Check: ip link  (no wlan0).\n   The agent runs without admin rights (step 4), so it can't undo this. If you ever give\n   it admin rights, it could.\n\n3. Two wired networks\n   - Built-in Ethernet  -> the Mac. Fixed address 10.77.0.2/24, no router:\n       sudo nmcli con add type ethernet ifname eth0 con-name mac ipv4.method manual \\\n         ipv4.addresses 10.77.0.2/24 ipv4.never-default yes\n   - USB Ethernet adapter (eth1) -> the key's network switch -> your router (DHCP, the default).\n     With the key in SEALED the switch has no power: the agent box has no internet.\n\n4. The agent's own account, without admin rights\n     sudo adduser agent           (do NOT add it to the sudo group)\n   Install your agent software as \"agent\", in its home folder. Point it at the meter:\n     base URL  http://10.77.0.1:8080/v1\n     API key   any text (the meter ignores it)\n     streaming OFF (the meter answers whole replies)\n\n5. The key's ACT position\n   At boot, set GPIO 17 as an input with pull-up (add to /etc/rc.local or a systemd unit):\n     pinctrl set 17 ip pu\n   Copy act-allowed.sh to /usr/local/bin/act-allowed (owned by root, not writable by agent).\n   Have the agent's tool policy run it before any action that changes something outside\n   its own folder, and refuse when it prints \"no\".\n   Honest limit: SEALED is enforced by hardware (the switch loses power). ACT is enforced by\n   the agent's software reading the key. Say so to anyone who asks.\n\n6. Checks\n     curl -s 10.77.0.1:8080/v1/models      -> lists the model\n     key to SEALED, then: ping -c1 1.1.1.1  -> fails\n     key to ONLINE: act-allowed            -> no\n     key to ACT:    act-allowed            -> yes\n", "sandtable-software/CONTROLLER-SETUP.txt": "CONTROLLER SETUP: Raspberry Pi Pico in the tray\n\n1. Arduino IDE (https://www.arduino.cc/en/software).\n   File > Preferences > Additional boards manager URLs:\n     https://github.com/earlephilhower/arduino-pico/releases/download/global/package_rp2040_index.json\n   Tools > Board > Boards Manager: install \"Raspberry Pi Pico/RP2040\" (Earle Philhower).\n   Tools > Board: \"Raspberry Pi Pico\" (not Pico W).\n\n2. Open sandtable-controller/sandtable-controller.ino.\n   Before the first upload, check MAX_DRIVE against your desk-test notes (start low: 0.3).\n   Hold BOOTSEL on the Pico, plug in USB, Upload.\n\n3. Choose your figure (the setup ritual, about 20 minutes, in a quiet room)\n   Sand on the plate, glass off, everyone watching.\n   - Press SETUP once. The plate slowly sweeps from low notes to high and shows every\n     figure it can make, one after another.\n   - When you see one you like, press SETUP. It now searches just around that note,\n     back and forth, slowly.\n   - Press SETUP again at the moment the figure is crispest. That note is saved; the\n     plate rings once to confirm. That is your figure from now on.\n   - Hold SETUP for 3 seconds at any time to cancel.\n   Or by laptop over the Pico's USB (Arduino Serial Monitor, 115200, newline):\n     f 312.5     hold the plate at 312.5 Hz\n     save 312.5  make it your figure\n     test 90     play a verdict at 90 (settled); try 30 to see unsettled\n     thresh 50   below this a task also counts on the UNSETTLED counter\n     show        print the saved settings\n\n4. The counters only ever count up. Nothing in the firmware can turn them back.\n", "sandtable-software/HONEST-VERSION-SETUP.txt": "HONEST-VERSION SETUP: Tier 2, the agent on its own machine\n\nEverything in the kitchen-table version, plus the parts that make \"measured, not reported\"\nphysical: the agent lives on a Raspberry Pi with no other way to the meter than one cable,\nand verdicts reach the plate down a one-way wire, through a controller nothing can talk back to.\n\nYour computer (macOS or Linux) runs the model and the meter. The Pi runs the agent.\nThe plate is driven by the Pico controller, not by the computer's sound.\n\n1. Your computer: the meter's own account\n   macOS: MAC-SETUP.txt steps 1 (accounts), 4 (model), 5 (meter) and 6 (start at boot).\n     Skip step 2: this computer keeps its Wi-Fi and its everyday use.\n   Linux: create a standard user \"meter\" (sudo adduser meter, not in the sudo group).\n     Install llama.cpp and put the model in /home/meter/models/. As meter:\n       mkdir -p /home/meter/lib\n       python3 -m pip install --target /home/meter/lib pyserial\n     Copy meter.py to /home/meter/. Copy linux/sandtable-model.service and\n     linux/sandtable-meter.service to /etc/systemd/system/, set the model file name, then:\n       sudo systemctl enable --now sandtable-model sandtable-meter\n     Add meter to the group that owns the serial port (often dialout): sudo usermod -aG dialout meter\n\n2. One cable to the Pi\n   Most laptops need a USB Ethernet adapter for this. Give that port a fixed address:\n   10.77.0.1, subnet 255.255.255.0, no router (macOS: MAC-SETUP.txt step 3).\n   This cable carries nothing but the agent's requests to the meter.\n\n3. The firewall: only the cable is locked down\n   This firewall leaves your computer's own internet alone. On the cable to the Pi it lets the\n   agent reach the meter's port 8080, and nothing else in either direction.\n   macOS: set LINK in mac/pf-sandtable-link-only.conf, then follow MAC-SETUP.txt step 7 with\n     that file in place of pf-sandtable.conf.\n   Linux: set LINK in linux/sandtable.nft, then:  sudo nft -f linux/sandtable.nft\n     To keep it after a reboot, include it from /etc/nftables.conf and enable nftables.\n\n4. The Pi (the agent box)\n   AGENT-BOX-SETUP.txt steps 1, 2 and 4, with these differences:\n   - Only the built-in Ethernet, to your computer (10.77.0.2). No USB adapter, no switch, no key:\n     the Pi has no internet. If your agent needs the web, that's the full build.\n   - Skip step 5 (the key).\n\n5. The controller\n   CONTROLLER-SETUP.txt as written: the same firmware, the same setup ritual.\n   Build only part of the board: the Pico, the PCM5102A DAC, the 24 to 5 V buck module,\n   two logic-level MOSFETs with a diode across each counter coil, and the one-way wire into GP1.\n   The amplifier and both counters run from one 24 V supply. Leave the light and\n   telltale pins unconnected: the firmware doesn't need them.\n   On the computer, find the USB-serial cable's name (macOS: ls /dev/cu.usbserial*;\n   Linux: ls /dev/ttyUSB*) and set it in the meter's start-up file.\n\n6. Checks, from the Pi\n     curl -s 10.77.0.1:8080/v1/models     -> lists the model\n     curl -s 10.77.0.1:8081/health        -> must fail (the model itself is unreachable)\n     ssh 10.77.0.1                        -> must fail\n     ping -c1 1.1.1.1                     -> must fail (no internet)\n   Then run a task: the TASKS counter clicks, and below 50 so does UNSETTLED.\n\nWhat it gives up, compared with the full build\n   Your computer is shared with your everyday life, not a machine that does nothing else, so\n   its security is only as good as its settings. There is no key (the agent never goes online or\n   acts in the world), no lights, and no case that hides the wiring. The isolation itself is real:\n   the agent's only path is one cable, and the table can't talk back.\n", "sandtable-software/KITCHEN-TABLE-SETUP.txt": "KITCHEN-TABLE SETUP: Tier 1, one computer, no controller\n\nEverything runs on one computer you already own (macOS, Linux or Windows): the model,\nthe meter, and the agent. The meter plays each verdict to the plate through a USB sound\nadapter. Read \"What it gives up\" at the end before you show it to anyone.\n\n1. The plate on the table\n   Do the desk test's setup (the-sand-table-desk-test.pdf): plate on the driver through its\n   centre hole, edges free, over a tray; amplifier gain all the way down.\n   Plug the USB sound adapter into the computer and run its output to the amplifier's input.\n   Use this adapter for the plate and nothing else. In the computer's sound settings, set\n   the adapter's volume to 100% once, and keep your normal speakers as the default output,\n   so notifications and videos never shake the sand.\n\n2. The model (llama.cpp)\n   macOS:   brew install llama.cpp\n   Linux / Windows: download a release from https://github.com/ggml-org/llama.cpp/releases\n   A small model that supports tool calls is enough (1 to 8 billion parameters runs on an\n   ordinary laptop). Start it on this computer only:\n     llama-server -m your-model.gguf --host 127.0.0.1 --port 8081\n   Check it gives word probabilities:\n     curl -s 127.0.0.1:8081/v1/chat/completions -H 'Content-Type: application/json' \\\n       -d '{\"messages\":[{\"role\":\"user\",\"content\":\"Say hi\"}],\"logprobs\":true,\"top_logprobs\":10}' \\\n       | python3 -m json.tool | grep -c top_logprobs\n   A number above 0 means it works. Most hosted AI services don't give word probabilities,\n   so the table can't read them: it needs a model you run yourself.\n\n3. The plate's sound\n   python3 -m pip install sounddevice        (Linux: also sudo apt install libportaudio2)\n   In the software folder:\n     python3 plate.py devices                (find the USB adapter's name)\n     python3 plate.py use USB                (any part of its name)\n     python3 plate.py drive 0.3              (the loudness ceiling; start here)\n   Choose your figure (about 15 minutes, sand on the plate, ear protection on):\n     python3 plate.py sweep\n   Press Enter when you see a figure you like; it searches around it. Press Enter again at\n   the crispest moment. If your desk test already found a good note: python3 plate.py save 312\n   Then turn the amplifier up until a test verdict forms the figure in about 3 seconds:\n     python3 plate.py test 95                (settled)\n     python3 plate.py test 30                (unsettled: the figure should smear)\n   Raise \"drive\" only if the amplifier is at its limit. The amplifier's knob and \"drive\" are\n   the only loudness limits in this version: note both.\n\n4. The meter\n   macOS / Linux:\n     SANDTABLE_OUTPUT=audio SANDTABLE_LISTEN=127.0.0.1 python3 meter.py\n   Windows (PowerShell):\n     $env:SANDTABLE_OUTPUT=\"audio\"; $env:SANDTABLE_LISTEN=\"127.0.0.1\"; python meter.py\n   It says: meter listening on 127.0.0.1:8080, verdicts to the plate (audio).\n\n5. The agent\n   Point your agent software at the meter, never at the model directly:\n     base URL  http://127.0.0.1:8080/v1\n     API key   any text (the meter ignores it)\n     streaming OFF\n   Give it a task. When it finishes, the plate plays the verdict. The log is\n   sandtable-log.csv in your home folder, with a column to mark whether each task was right.\n\nWhat it gives up\n   The agent, the model and the meter share one computer. \"The agent can't reach the meter\"\n   is a software promise here, not a physical one: anything running on the computer could\n   read the meter's numbers, call the model directly without being measured, or play sounds\n   of its own. There are no counters and no\n   controller-held loudness limit. That's fine for a demo, as long as the placard says so.\n", "sandtable-software/MAC-SETUP.txt": "MAC STUDIO SETUP: the model and the meter, nothing else\n\n1. Accounts\n   - Your own admin account, used only for setup and updates.\n   - A standard (not admin) account named \"meter\":\n       System Settings > Users & Groups > Add User... > Standard, name \"meter\".\n   - There is no account for the agent.\n\n2. Close every other door\n   - Wi-Fi off. Bluetooth off.\n   - System Settings > General > Sharing: everything off (File Sharing, Screen Sharing,\n     Remote Login, Remote Management, Media Sharing, AirPlay Receiver).\n   - The Mac has one network cable: to the agent box. It has no internet in normal use.\n     For updates, follow step 9: the firewall blocks them while it is on.\n\n3. The link to the agent box\n   System Settings > Network > the Ethernet port wired to the agent box >\n   Details > TCP/IP: Configure IPv4 Manually, IP 10.77.0.1, Subnet 255.255.255.0, no router.\n   Find that port's name (en0, en1...):  networksetup -listallhardwareports\n\n4. Model runtime (llama.cpp)\n   brew install llama.cpp          (needs Homebrew: https://brew.sh, while on the internet)\n   Put the model file (.gguf) in /Users/meter/models/ and set its name in\n   org.sandtable.model.plist. Choose a model that supports tool calls.\n   Check that it gives word probabilities (run as meter, with the model started):\n     curl -s 127.0.0.1:8081/v1/chat/completions -H 'Content-Type: application/json' \\\n       -d '{\"messages\":[{\"role\":\"user\",\"content\":\"Say hi\"}],\"logprobs\":true,\"top_logprobs\":10}' \\\n       | python3 -m json.tool | grep -c top_logprobs\n   A number above 0 means it works. If it prints 0, update llama.cpp.\n\n5. Meter\n   Install pyserial into a fixed folder the meter's start-up file points to (as meter):\n     mkdir -p /Users/meter/lib\n     /usr/bin/python3 -m pip install --target /Users/meter/lib pyserial\n   Check it is found the way it will be at boot:\n     PYTHONPATH=/Users/meter/lib /usr/bin/python3 -c \"import serial; print('ok')\"\n   Copy meter.py to /Users/meter/meter.py\n   Plug in the USB-serial adapter (receive wire already cut) and find its name:\n     ls /dev/cu.usbserial*\n   Put that name in org.sandtable.meter.plist.\n\n6. Start both at boot, as the meter's user\n   sudo cp org.sandtable.model.plist org.sandtable.meter.plist /Library/LaunchDaemons/\n   sudo chown root:wheel /Library/LaunchDaemons/org.sandtable.*.plist\n   sudo launchctl bootstrap system /Library/LaunchDaemons/org.sandtable.model.plist\n   sudo launchctl bootstrap system /Library/LaunchDaemons/org.sandtable.meter.plist\n\n7. Firewall\n   Set LINK in pf-sandtable.conf to the port from step 3, then:\n     sudo cp pf-sandtable.conf /etc/pf.anchors/sandtable\n     sudo pfctl -nf /etc/pf.anchors/sandtable        (checks it; prints nothing if fine)\n   To load it at every boot, add these two lines to the end of /etc/pf.conf:\n     anchor \"sandtable\"\n     load anchor \"sandtable\" from \"/etc/pf.anchors/sandtable\"\n   then: sudo pfctl -ef /etc/pf.conf\n   macOS updates sometimes replace /etc/pf.conf: check it after each update.\n\n8. Check from the agent box (after its setup)\n     curl -s 10.77.0.1:8080/v1/models         -> works\n     curl -s 10.77.0.1:8081/health            -> must fail (the model itself is unreachable)\n     ssh 10.77.0.1                            -> must fail\n\n9. Updates (macOS, llama.cpp, the model)\n   The firewall blocks everything except the agent box's one port, updates included.\n   So the agent box is never connected while the firewall is off:\n     a. Unplug the agent box's cable from the Mac.\n     b. Switch the firewall off:  sudo pfctl -d\n     c. Plug the Mac into your router, update (Software Update; brew upgrade llama.cpp), unplug.\n     d. Check /etc/pf.conf still ends with the two sandtable lines from step 7 (updates can\n        replace it), then switch the firewall back on:  sudo pfctl -ef /etc/pf.conf\n     e. Check it is on:  sudo pfctl -s info | head -1   -> \"Status: Enabled\"\n     f. Plug the agent box back in, and run the checks in step 8.\n", "sandtable-software/README.txt": "THE SAND TABLE: SOFTWARE\n\nThree machines, three jobs, and they never share one:\n\n  agent box (Raspberry Pi 5)    the agent: its loop, its tools, its files. Thinks by asking the Mac.\n  Mac Studio                    the model and the meter. Nothing else. No account for the agent.\n  controller (Raspberry Pi Pico, no radio, in the tray)\n                                turns one number into the sand figure. Listens; never talks back.\n\n  agent box --one Ethernet cable--> Mac (firewall: model requests only)\n  Mac --one-way serial wire--> controller (the adapter's receive wire is cut)\n\nFiles\n  meter.py                         the meter. Runs on the Mac as user \"meter\".\n  mac/org.sandtable.model.plist    starts llama-server for the meter's user, on this Mac only\n  mac/org.sandtable.meter.plist    starts the meter\n  mac/pf-sandtable.conf            firewall for the cable to the agent box\n  pi/act-allowed.sh                reads the key's ACT position on the agent box\n  sandtable-controller/            firmware for the Pico (Arduino IDE)\n  MAC-SETUP.txt, AGENT-BOX-SETUP.txt, CONTROLLER-SETUP.txt   step by step\n\nSmaller versions (the-sand-table-small-versions.pdf)\n  KITCHEN-TABLE-SETUP.txt          Tier 1: one computer, no controller; the meter plays the plate\n  plate.py                         Tier 1: the plate's sound from the computer, and the setup sweep\n  HONEST-VERSION-SETUP.txt         Tier 2: the agent on a Raspberry Pi, your own computer as the meter\n  mac/pf-sandtable-link-only.conf  Tier 2: firewall for the cable only, on a Mac you also use daily\n  linux/                           Tier 2: the same firewall and the start-up files for Linux\n\nThe number\n  For every reply the model gives (a tool call or an answer), the meter looks at the\n  shakiest 10% of its words: how spread the model's probability was over its top 10\n  choices. A task's number is its WORST reply, so one torn step can't hide inside a\n  confident task. 100 = settled, 0 = unsettled.\n\n  Settled is not the same as right. The figure shows how the model behaved, not\n  whether its work was correct. The log (~meter/sandtable-log.csv) has an empty\n  column for a person to mark whether each task was actually right; over months that\n  shows what a crisp figure is worth in your house.\n\n  The agent can't shape what's measured. The meter takes only the conversation, the\n  tools and a length limit from the agent's request, and sets every sampling setting\n  itself (temperature, logit bias, grammar and format are dropped).\n\n  Worth watching: the fixed parts of a tool call (its brackets and field names) are\n  forced by the format, so they read as very settled. The shakiest-10% rule mostly\n  handles that, but check the log's tool_calls column: if tool-heavy tasks come out\n  crisper than they deserve, that's a calibration finding.\n\nNot tested on hardware yet: the meter was tested against a stand-in model server;\nthe firmware has not been compiled. Do both on the bench (guide, section 7).\n", "sandtable-software/meter.py": "#!/usr/bin/env python3\n\"\"\"\nThe Sand Table meter.\n\nRuns on the Mac Studio as its own user (\"meter\"), next to the model runtime it owns.\nThe agent lives on a separate small computer and reaches the model only through this\nprogram, over the one cable between the two machines. The agent never sees the\nprobabilities, never sees the sand table, and cannot start, stop or configure the model.\n\nWhat it does, in order:\n  1. Passes each model request from the agent box to llama-server (local only),\n     asking it for the top word probabilities at every step.\n  2. For each reply (a \"decision\": a tool call or a final answer) it works out how\n     unsettled the model was at its shakiest moments.\n  3. When a task ends, it takes the WORST decision in the task, turns it into one\n     number (0 = completely unsettled, 100 = completely settled) and sends it out\n     the one-way serial wire to the sand table's controller.\n  4. Writes one line per task to a log, with an empty column for a person to mark\n     later whether the work was actually right.\n\nIt is arithmetic only. No second model, nothing that reads the meaning of the text.\n\nNeeds: Python 3.9+, and pyserial, installed where the start-up file looks (MAC-SETUP.txt, step 5).\nThe kitchen-table version needs sounddevice instead (see plate.py), and runs with\nSANDTABLE_OUTPUT=audio SANDTABLE_LISTEN=127.0.0.1.\n\"\"\"\nimport csv, json, math, os, sys, threading, time, urllib.request\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\n\n# ---------------------------------------------------------------- settings\n# Where the agent reaches the meter: the Mac's address on the one cable to the agent box.\n# The kitchen-table version, with the agent on this same computer, uses 127.0.0.1.\nLISTEN_HOST = os.environ.get(\"SANDTABLE_LISTEN\", \"10.77.0.1\")\nLISTEN_PORT = 8080                   # the only port the firewall opens to the agent box\nMODEL_URL   = \"http://127.0.0.1:8081\"   # llama-server, bound to this Mac only\nSERIAL_PORT = os.environ.get(\"SANDTABLE_SERIAL\", \"/dev/cu.usbserial-0001\")\nBAUD        = 9600\n# \"wire\": verdicts go down the one-way wire to the controller (the full build, and Tier 2).\n# \"audio\": no controller; this computer plays each verdict to the plate itself (plate.py).\nOUTPUT      = os.environ.get(\"SANDTABLE_OUTPUT\", \"wire\")\nTOP_K       = 10                     # alternatives per word the meter looks at\nSHAKY_SHARE = 0.10                   # a decision's score = mean of its shakiest 10% of words\nTASK_IDLE_S = 120                    # no model request for this long also ends a task\nMAX_TOKENS  = 8192                   # the longest reply the agent may ask for\n# The only fields taken from the agent's request. Everything else it sends is dropped.\nAGENT_FIELDS = (\"messages\", \"tools\", \"tool_choice\", \"max_tokens\")\n# How the model runs, set by the meter on every request so the agent can't sharpen the\n# probabilities it is measured by (no temperature, logit bias, grammar or format of its own).\n# These are llama-server's usual defaults, written out. post_sampling_probs False asks for\n# the model's own probabilities, before any sampling step.\nSAMPLING = {\"temperature\": 0.8, \"top_k\": 40, \"top_p\": 0.95, \"min_p\": 0.05,\n            \"post_sampling_probs\": False}\nLOG_PATH    = os.path.expanduser(\"~/sandtable-log.csv\")\n\n# ---------------------------------------------------------------- the one-way wire\nclass Wire:\n    \"\"\"Writes short lines to the controller. Never reads: the adapter's receive wire is cut.\"\"\"\n    def __init__(self, port):\n        self.port, self.s, self.lock = port, None, threading.Lock()\n    def send(self, line):\n        with self.lock:\n            try:\n                if self.s is None:\n                    import serial\n                    self.s = serial.Serial(self.port, BAUD, timeout=0, write_timeout=1)\n                self.s.write((line + \"\\n\").encode(\"ascii\"))\n            except Exception as e:           # unplugged: keep the model running, try again later\n                self.s = None\n                print(\"wire:\", e, file=sys.stderr)\n\nif OUTPUT == \"audio\":\n    import plate\n    wire = plate.Plate()\nelse:\n    wire = Wire(SERIAL_PORT)\n\n# ---------------------------------------------------------------- arithmetic\ndef word_unsettledness(top_logprobs):\n    \"\"\"0 = all probability on one word, 1 = spread evenly over the top-k and the rest.\"\"\"\n    ps = [math.exp(lp) for lp in top_logprobs[:TOP_K]]\n    rest = max(0.0, 1.0 - sum(ps))\n    if rest > 1e-9:\n        ps.append(rest)\n    h = -sum(p * math.log(p) for p in ps if p > 0)\n    return min(1.0, h / math.log(TOP_K + 1))\n\ndef decision_unsettledness(words):\n    \"\"\"Mean of the shakiest share of words, so a confident ending can't hide a torn middle.\"\"\"\n    if not words:\n        return None\n    w = sorted(words, reverse=True)\n    n = max(1, int(len(w) * SHAKY_SHARE))\n    return sum(w[:n]) / n\n\ndef words_from_reply(reply):\n    \"\"\"Reads OpenAI-style logprobs from llama-server's chat reply.\"\"\"\n    out = []\n    try:\n        content = reply[\"choices\"][0][\"logprobs\"][\"content\"] or []\n    except (KeyError, IndexError, TypeError):\n        return out\n    for item in content:\n        alts = [a[\"logprob\"] for a in item.get(\"top_logprobs\", []) if \"logprob\" in a]\n        if alts:\n            out.append(word_unsettledness(sorted(alts, reverse=True)))\n    return out\n\n# ---------------------------------------------------------------- tasks\nclass Tasks:\n    def __init__(self):\n        self.lock = threading.Lock()\n        self.reset()\n        self.last_request = 0.0\n        self.busy = 0\n    def reset(self):\n        self.decisions, self.tools, self.started = [], 0, None\n    def decision(self, u, tool_call):\n        with self.lock:\n            if self.started is None:\n                self.started = time.time()\n            if u is not None:\n                self.decisions.append(u)\n            if tool_call:\n                self.tools += 1\n    def end(self, why):\n        with self.lock:\n            if self.started is None or not self.decisions:\n                self.reset()\n                return\n            worst = max(self.decisions)\n            settled = round(100 * (1 - worst))\n            row = [time.strftime(\"%Y-%m-%d %H:%M:%S\"), settled, len(self.decisions), self.tools,\n                   why, round(time.time() - self.started), \"\"]\n            self.reset()\n        wire.send(\"V%d\" % settled)\n        new = not os.path.exists(LOG_PATH)\n        with open(LOG_PATH, \"a\", newline=\"\") as f:\n            w = csv.writer(f)\n            if new:\n                w.writerow([\"time\", \"settled_0_100\", \"decisions\", \"tool_calls\", \"ended_by\",\n                            \"seconds\", \"was_it_right (a person fills this in)\"])\n            w.writerow(row)\n\ntasks = Tasks()\n\n# ---------------------------------------------------------------- the proxy\nALLOWED = (\"/v1/chat/completions\", \"/v1/models\")\n\nclass Handler(BaseHTTPRequestHandler):\n    protocol_version = \"HTTP/1.1\"\n    def log_message(self, *a):\n        pass\n    def _reply(self, code, body):\n        data = json.dumps(body).encode()\n        self.send_response(code)\n        self.send_header(\"Content-Type\", \"application/json\")\n        self.send_header(\"Content-Length\", str(len(data)))\n        self.end_headers()\n        self.wfile.write(data)\n    def do_GET(self):\n        if self.path != \"/v1/models\":\n            return self._reply(404, {\"error\": \"not here\"})\n        with urllib.request.urlopen(MODEL_URL + \"/v1/models\", timeout=10) as r:\n            self._reply(200, json.loads(r.read()))\n    def do_POST(self):\n        if self.path not in ALLOWED:\n            return self._reply(404, {\"error\": \"not here\"})\n        try:\n            req = json.loads(self.rfile.read(int(self.headers.get(\"Content-Length\", 0))))\n        except Exception:\n            return self._reply(400, {\"error\": \"bad json\"})\n        if not isinstance(req, dict) or not isinstance(req.get(\"messages\"), list):\n            return self._reply(400, {\"error\": \"messages required\"})\n        # The meter decides how the model runs. From the agent it takes only the conversation,\n        # the tools it may call and a length limit; all sampling settings are the meter's own.\n        req = {k: req[k] for k in AGENT_FIELDS if k in req}\n        if \"max_tokens\" in req:\n            try:\n                req[\"max_tokens\"] = max(1, min(MAX_TOKENS, int(req[\"max_tokens\"])))\n            except (TypeError, ValueError):\n                del req[\"max_tokens\"]\n        req.update(SAMPLING)\n        req[\"stream\"] = False\n        req[\"logprobs\"] = True\n        req[\"top_logprobs\"] = TOP_K\n        with tasks.lock:\n            tasks.last_request = time.time()\n            tasks.busy += 1\n        wire.send(\"W1\")\n        try:\n            r = urllib.request.Request(MODEL_URL + \"/v1/chat/completions\",\n                                       data=json.dumps(req).encode(),\n                                       headers={\"Content-Type\": \"application/json\"})\n            with urllib.request.urlopen(r, timeout=900) as resp:\n                reply = json.loads(resp.read())\n        except Exception as e:\n            return self._reply(502, {\"error\": \"model unavailable: %s\" % e})\n        finally:\n            with tasks.lock:\n                tasks.busy -= 1\n                done = tasks.busy == 0\n            if done:\n                wire.send(\"W0\")\n        choice = (reply.get(\"choices\") or [{}])[0]\n        msg = choice.get(\"message\") or {}\n        tool_call = bool(msg.get(\"tool_calls\"))\n        if tool_call:\n            wire.send(\"T\")\n        tasks.decision(decision_unsettledness(words_from_reply(reply)), tool_call)\n        if choice.get(\"finish_reason\") == \"stop\" and not tool_call:\n            tasks.end(\"answer\")\n        choice.pop(\"logprobs\", None)          # the agent never sees the probabilities\n        self._reply(200, reply)\n\n# ---------------------------------------------------------------- heartbeat\ndef heartbeat():\n    while True:\n        idle = time.time() - tasks.last_request\n        if tasks.started is not None and tasks.busy == 0 and idle > TASK_IDLE_S:\n            tasks.end(\"idle\")\n        try:\n            urllib.request.urlopen(MODEL_URL + \"/health\", timeout=3).read()\n            wire.send(\"H1\" if idle < 600 else \"H0\")     # H0 = on but resting: the gap light breathes\n        except Exception:\n            pass                                          # no heartbeat: the controller shows \"off\"\n        time.sleep(5)\n\nif __name__ == \"__main__\":\n    threading.Thread(target=heartbeat, daemon=True).start()\n    print(\"meter listening on %s:%d, verdicts to the %s\" % (LISTEN_HOST, LISTEN_PORT, \"plate (audio)\" if OUTPUT == \"audio\" else \"wire\"))\n    ThreadingHTTPServer((LISTEN_HOST, LISTEN_PORT), Handler).serve_forever()\n", "sandtable-software/plate.py": "#!/usr/bin/env python3\n\"\"\"\nThe Sand Table plate, played straight from the computer.\n\nFor the kitchen-table version (Tier 1), which has no controller: the meter plays each verdict\nthrough a USB sound adapter into the amplifier and the driver. It makes the same sound as\nthe controller's firmware: the household's one note, with noise and a slight wander mixed\nin when the agent was unsettled, 0.4 s up, 3.5 s hold, 0.3 s down.\n\nUse a USB sound adapter for the plate and nothing else, so notifications, videos and other\nprograms never shake the sand. Set that adapter's own volume to 100% once; the ceiling is\nmax_drive here and the amplifier's gain knob.\n\nSetup, by hand (python3 plate.py <command>):\n  devices            list sound outputs\n  use <name>         play the plate through the output whose name contains <name>\n  sweep              slowly play every note from 80 to 1200 Hz (about 14 minutes).\n                     Press Enter when you see a figure you like: it searches just around it.\n                     Press Enter again at the crispest moment: that is your figure.\n  f <hz>             hold one note until you press Enter\n  save <hz>          make <hz> your figure\n  drive <0-1>        loudness ceiling, as a fraction of full scale (start at 0.30)\n  test <0-100>       play a verdict: 95 settled, 30 unsettled\n  wav <0-100> <file> write a verdict to a WAV file instead of playing it\n  show               print the settings\n\nNeeds: Python 3.9+, and sounddevice (python3 -m pip install sounddevice; on Linux also\nsudo apt install libportaudio2). Writing WAV files needs nothing extra.\n\"\"\"\nimport json, math, os, queue, sys, threading, wave\n\nRATE = 32000\nF_LO, F_HI = 80.0, 1200.0\nSETTINGS = os.path.expanduser(os.environ.get(\"SANDTABLE_PLATE\", \"~/.sandtable-plate.json\"))\nDEFAULTS = {\"device\": None, \"f0\": 0.0, \"max_drive\": 0.30}\n\n\ndef load():\n    s = dict(DEFAULTS)\n    try:\n        with open(SETTINGS) as f:\n            s.update(json.load(f))\n    except (OSError, ValueError):\n        pass\n    return s\n\n\ndef store(s):\n    with open(SETTINGS, \"w\") as f:\n        json.dump(s, f, indent=1)\n\n\nclass Voice:\n    \"\"\"The firmware's audio core: one note, with softened noise and a slow wander for unsettled.\"\"\"\n    def __init__(self, max_drive):\n        self.max_drive, self.phase, self.lp, self.wander, self.n = max_drive, 0.0, 0.0, 0.0, 0\n        self.rng = 2463534242\n\n    def noise(self):                          # the same xorshift as the controller\n        r = self.rng\n        r ^= (r << 13) & 0xFFFFFFFF; r ^= r >> 17; r ^= (r << 5) & 0xFFFFFFFF\n        self.rng = r\n        return (r - (1 << 32) if r >= 1 << 31 else r) / 2147483648.0\n\n    def render(self, seconds, freq, unsettled, level):\n        \"\"\"level: a number, or a function of time in seconds. Returns 16-bit mono samples.\"\"\"\n        out = bytearray()\n        for i in range(int(seconds * RATE)):\n            lvl = level(i / RATE) if callable(level) else level\n            self.n += 1\n            if self.n >= 256:\n                self.n = 0\n                self.wander = (self.wander + 0.08 * self.noise()) * 0.98\n            fe = freq * (1.0 + unsettled * 0.012 * self.wander)\n            self.phase = (self.phase + fe / RATE) % 1.0\n            s = math.sin(2 * math.pi * self.phase)\n            self.lp += 0.15 * (self.noise() - self.lp)\n            v = lvl * self.max_drive * ((1.0 - 0.6 * unsettled) * s + 0.6 * unsettled * self.lp * 2.0)\n            v = max(-self.max_drive, min(self.max_drive, v))   # a real ceiling: noise peaks are clipped\n            out += int(v * 32767).to_bytes(2, \"little\", signed=True)\n        return bytes(out)\n\n\ndef envelope(t):                              # 0.4 s up, 3.5 s hold, 0.3 s down\n    if t < 0.4:\n        return t / 0.4\n    if t < 3.9:\n        return 1.0\n    return max(0.0, 1.0 - (t - 3.9) / 0.3)\n\n\ndef verdict_clip(settled, s=None):\n    s = s or load()\n    if s[\"f0\"] <= 0:\n        return None                           # no figure chosen yet: do nothing rather than guess\n    u = min(1.0, max(0.0, (100 - settled) / 100.0))\n    return Voice(s[\"max_drive\"]).render(4.2, s[\"f0\"], u, envelope)\n\n\ndef write_wav(path, samples):\n    with wave.open(path, \"wb\") as w:\n        w.setnchannels(1); w.setsampwidth(2); w.setframerate(RATE)\n        w.writeframes(samples)\n\n\ndef stream(s):\n    import sounddevice as sd\n    st = sd.RawOutputStream(samplerate=RATE, channels=1, dtype=\"int16\", device=s[\"device\"])\n    st.start()\n    return st\n\n\nclass Plate:\n    \"\"\"Stands in for the one-way wire in meter.py: verdicts play, everything else is ignored.\"\"\"\n    def __init__(self):\n        self.q = queue.Queue(maxsize=4)\n        threading.Thread(target=self._run, daemon=True).start()\n\n    def send(self, line):\n        if line.startswith(\"V\"):\n            try:\n                self.q.put_nowait(int(line[1:]))\n            except (ValueError, queue.Full):\n                pass\n\n    def _run(self):\n        while True:\n            settled = self.q.get()\n            try:\n                s = load()\n                clip = verdict_clip(settled, s)\n                if clip:\n                    st = stream(s); st.write(clip); st.stop(); st.close()\n            except Exception as e:            # no adapter plugged in: keep the meter running\n                print(\"plate:\", e, file=sys.stderr)\n\n\ndef wait_enter():\n    flag = threading.Event()\n    threading.Thread(target=lambda: (sys.stdin.readline(), flag.set()), daemon=True).start()\n    return flag\n\n\ndef sweep(s):\n    v, st = Voice(s[\"max_drive\"]), stream(s)\n    print(\"Sweeping 80 to 1200 Hz. Press Enter when you see a figure you like (Ctrl-C to stop).\")\n    f, pressed = F_LO, wait_enter()\n    while f <= F_HI and not pressed.is_set():\n        st.write(v.render(0.3, f, 0.0, 0.7)); f *= 1.001\n    if not pressed.is_set():\n        print(\"Sweep finished without a choice.\"); return\n    center = f; f = center * 0.985\n    print(\"Searching around %.1f Hz. Press Enter at the crispest moment.\" % center)\n    pressed = wait_enter()\n    while not pressed.is_set():\n        st.write(v.render(1.5, f, 0.0, 0.7)); f *= 1.0005\n        if f > center * 1.015:\n            f = center * 0.985\n    s[\"f0\"] = round(f, 2); store(s); st.stop(); st.close()\n    print(\"Saved: your figure is %.2f Hz. Playing a settled verdict.\" % s[\"f0\"])\n    st = stream(s); st.write(verdict_clip(100, s)); st.stop()\n\n\ndef main(a):\n    s = load()\n    cmd = a[0] if a else \"show\"\n    if cmd == \"devices\":\n        import sounddevice as sd\n        print(sd.query_devices())\n    elif cmd == \"use\":\n        s[\"device\"] = \" \".join(a[1:]); store(s); print(\"plate output:\", s[\"device\"])\n    elif cmd == \"sweep\":\n        sweep(s)\n    elif cmd == \"f\":\n        v, st, pressed = Voice(s[\"max_drive\"]), stream(s), wait_enter()\n        print(\"Holding %s Hz. Press Enter to stop.\" % a[1])\n        while not pressed.is_set():\n            st.write(v.render(0.5, float(a[1]), 0.0, 0.7))\n    elif cmd == \"save\":\n        s[\"f0\"] = float(a[1]); store(s); print(\"saved\")\n    elif cmd == \"drive\":\n        s[\"max_drive\"] = min(1.0, max(0.0, float(a[1]))); store(s); print(\"saved\")\n    elif cmd in (\"test\", \"wav\"):\n        clip = verdict_clip(int(a[1]), s)\n        if clip is None:\n            print(\"Choose your figure first: python3 plate.py sweep\"); return\n        if cmd == \"wav\":\n            write_wav(a[2], clip); print(\"wrote\", a[2])\n        else:\n            st = stream(s); st.write(clip); st.stop()\n    else:\n        print(\"figure %.2f Hz, ceiling %.2f, output %s  (settings: %s)\" % (s[\"f0\"], s[\"max_drive\"], s[\"device\"] or \"default\", SETTINGS))\n\n\nif __name__ == \"__main__\":\n    try:\n        main(sys.argv[1:])\n    except KeyboardInterrupt:\n        print()\n", "sandtable-software/linux/sandtable-meter.service": "# The meter: the only door from the agent box to the model. Copy to /etc/systemd/system/.\n[Unit]\nDescription=Sand Table meter\nAfter=network-online.target sandtable-model.service\n\n[Service]\nUser=meter\nEnvironment=SANDTABLE_SERIAL=/dev/ttyUSB0\nEnvironment=PYTHONPATH=/home/meter/lib\nExecStart=/usr/bin/python3 /home/meter/meter.py\nRestart=always\n\n[Install]\nWantedBy=multi-user.target\n", "sandtable-software/linux/sandtable-model.service": "# The model, run as the meter's own user. Copy to /etc/systemd/system/, set the model file, then:\n#   sudo systemctl enable --now sandtable-model sandtable-meter\n[Unit]\nDescription=Sand Table model (llama-server, this computer only)\nAfter=network.target\n\n[Service]\nUser=meter\nExecStart=/usr/local/bin/llama-server -m /home/meter/models/your-model.gguf --host 127.0.0.1 --port 8081\nRestart=always\n\n[Install]\nWantedBy=multi-user.target\n", "sandtable-software/linux/sandtable.nft": "#!/usr/sbin/nft -f\n# Sand Table firewall for the honest version (Tier 2) on Linux.\n# It locks down only the cable to the agent box; the computer's other networks are untouched.\n# Set LINK to the port wired to the agent box (see: ip link), then:\n#   sudo cp sandtable.nft /etc/nftables.d/ (or include it from /etc/nftables.conf)\n#   sudo nft -f /etc/nftables.d/sandtable.nft\ndefine LINK = \"eth1\"\ndefine AGENT = 10.77.0.2\n\ntable inet sandtable\ndelete table inet sandtable\ntable inet sandtable {\n  chain input {\n    type filter hook input priority -10; policy accept;\n    iifname $LINK ip saddr $AGENT tcp dport 8080 ct state new,established accept\n    iifname $LINK drop\n  }\n  chain output {\n    type filter hook output priority -10; policy accept;\n    oifname $LINK ct state established accept\n    oifname $LINK drop\n  }\n  chain forward {\n    type filter hook forward priority -10; policy accept;\n    iifname $LINK drop\n    oifname $LINK drop\n  }\n}\n", "sandtable-software/mac/org.sandtable.meter.plist": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<!-- The meter: the only door from the agent box to the model. -->\n<plist version=\"1.0\"><dict>\n  <key>Label</key><string>org.sandtable.meter</string>\n  <key>UserName</key><string>meter</string>\n  <key>ProgramArguments</key><array>\n    <string>/usr/bin/python3</string><string>/Users/meter/meter.py</string>\n  </array>\n  <key>EnvironmentVariables</key><dict>\n    <key>SANDTABLE_SERIAL</key><string>/dev/cu.usbserial-0001</string>\n    <key>PYTHONPATH</key><string>/Users/meter/lib</string>\n  </dict>\n  <key>RunAtLoad</key><true/>\n  <key>KeepAlive</key><true/>\n  <key>StandardErrorPath</key><string>/Users/meter/meter.log</string>\n</dict></plist>\n", "sandtable-software/mac/org.sandtable.model.plist": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE plist PUBLIC \"-//Apple//DTD PLIST 1.0//EN\" \"http://www.apple.com/DTDs/PropertyList-1.0.dtd\">\n<!-- The model runtime. Owned by the meter's user; listens on this Mac only. -->\n<plist version=\"1.0\"><dict>\n  <key>Label</key><string>org.sandtable.model</string>\n  <key>UserName</key><string>meter</string>\n  <key>ProgramArguments</key><array>\n    <string>/opt/homebrew/bin/llama-server</string>\n    <string>-m</string><string>/Users/meter/models/MODEL.gguf</string>\n    <string>--host</string><string>127.0.0.1</string>\n    <string>--port</string><string>8081</string>\n    <string>-c</string><string>32768</string>\n    <string>--jinja</string>\n  </array>\n  <key>RunAtLoad</key><true/>\n  <key>KeepAlive</key><true/>\n  <key>StandardErrorPath</key><string>/Users/meter/model.log</string>\n</dict></plist>\n", "sandtable-software/mac/pf-sandtable-link-only.conf": "# Sand Table firewall for the honest version (Tier 2), on a computer you also use every day.\n# It locks down only the cable to the agent box; the computer's own Wi-Fi and internet are untouched.\n# Set LINK to the port wired to the agent box (often a USB Ethernet adapter):\n#   networksetup -listallhardwareports\n# Load and make permanent exactly as in MAC-SETUP.txt, step 7, using this file instead.\nLINK = \"en5\"\nAGENT = \"10.77.0.2\"\nHOST  = \"10.77.0.1\"\n\n# The agent box may ask the meter for model replies. Nothing else on this cable, in either direction.\npass in quick on $LINK proto tcp from $AGENT to $HOST port 8080 flags S/SA keep state\nblock drop quick on $LINK all\n", "sandtable-software/mac/pf-sandtable.conf": "# Sand Table firewall for the Mac Studio's link to the agent box.\n# Load with: sudo pfctl -f /etc/pf.anchors/sandtable  (see MAC-SETUP.txt for making it permanent)\n# Set LINK to the Mac's port wired to the agent box (find it with: networksetup -listallhardwareports)\n# This blocks everything else, the Mac's own updates included. To update, follow \"9. Updates\" in\n# MAC-SETUP.txt: unplug the agent box first, then switch this off, update, and switch it back on.\nLINK = \"en0\"\nAGENT = \"10.77.0.2\"\nMAC   = \"10.77.0.1\"\n\nset skip on lo0\nblock drop all\n# The agent box may ask the meter for model replies. Nothing else, in either direction.\npass in quick on $LINK proto tcp from $AGENT to $MAC port 8080 flags S/SA keep state\n", "sandtable-software/pi/act-allowed.sh": "#!/bin/sh\n# Prints \"yes\" if the key is in ACT, \"no\" otherwise. The agent's tool policy calls this\n# before any action that changes something (sending, buying, deleting, writing outside its folder).\n# The key's ACT contact pulls GPIO 17 to ground.\nif pinctrl get 17 | grep -q \" lo\"; then echo yes; else echo no; fi\n", "sandtable-software/sandtable-controller/sandtable-controller.ino": "/*\n  The Sand Table controller.\n\n  Board:   Raspberry Pi Pico (RP2040). The plain Pico, NOT the Pico W: no radio.\n  Core:    \"Raspberry Pi Pico/RP2040\" by Earle Philhower, in the Arduino IDE\n           (Boards Manager URL: https://github.com/earlephilhower/arduino-pico/releases/download/global/package_rp2040_index.json)\n\n  It listens on one wire and never talks back. From the meter it receives short lines:\n    V<0-100>  a task ended; how settled the agent was (100 = completely settled)\n    W1 / W0   the model is working / has stopped\n    T         the model made a tool call\n    H1 / H0   heartbeat: machine on / machine on but resting\n  No heartbeat for 20 s means the machine is off.\n\n  It drives the brass plate through an I2S DAC and an amplifier: always the household's own\n  figure (one resonant note, chosen at setup), with clarity = how settled the agent was.\n  Unsettled adds noise and a slight wander to the drive, so the figure smears and the\n  tone goes grainy. The same vibration makes the sound and the figure.\n\n  Pins (all 3.3 V logic):\n    GP1   one-way wire in (UART0 RX). GP0 is NOT connected.\n    GP20  I2S BCK   GP21 I2S LRCK   GP22 I2S DIN     -> PCM5102A DAC -> amplifier -> driver\n    GP10  TASKS counter     (through a logic-level MOSFET to the 24 V counter coil)\n    GP11  UNSETTLED counter (same)\n    GP12  WORKING telltale LED      GP13 TOOL telltale LED\n    GP14  gap light (MOSFET, PWM)   GP15 raking light (MOSFET, PWM)\n    GP18  heartbeat pilot LED (the small blink when the machine is off)\n    GP16  SETUP button to ground    GP17 LIGHTS switch to ground = all lights off\n*/\n#include <I2S.h>\n#include <EEPROM.h>\n\n// ------------------------------------------------------------ limits set at the desk test\nconst float MAX_DRIVE   = 0.30f;   // fraction of full scale: start here, raise to match your desk test. Also cap the amplifier's own gain.\nconst float F_LO = 80.0f, F_HI = 1200.0f;\nconst uint32_t RATE = 32000;\n\n// ------------------------------------------------------------ pins\nconst int P_TASKS = 10, P_UNSET = 11, P_WORK = 12, P_TOOL = 13, P_GAP = 14, P_RAKE = 15,\n          P_SETUP = 16, P_LIGHTS = 17, P_PILOT = 18;\n\n// ------------------------------------------------------------ saved settings\nstruct Saved { uint32_t magic; float f0; int thresh; uint32_t verdicts; } saved;\nconst uint32_t MAGIC = 0x53414E44;  // \"SAND\"\nvoid loadSaved() {\n  EEPROM.begin(256); EEPROM.get(0, saved);\n  if (saved.magic != MAGIC) { saved = {MAGIC, 0.0f, 50, 0}; }\n}\nvoid storeSaved() { EEPROM.put(0, saved); EEPROM.commit(); }\n\n// ------------------------------------------------------------ shared with the audio core\nvolatile float vFreq = 0, vUnsettled = 0, vLevel = 0;   // level 0..1, already enveloped\n\n// ------------------------------------------------------------ audio core (core 1)\nI2S i2s(OUTPUT);\nint16_t sine[1024];\nuint32_t rng = 2463534242u;\ninline float noise() { rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5; return (int32_t)rng / 2147483648.0f; }\n\nvoid setup1() {\n  for (int i = 0; i < 1024; i++) sine[i] = (int16_t)(32767 * sinf(2 * PI * i / 1024));\n  i2s.setBCLK(20); i2s.setDATA(22); i2s.setBitsPerSample(16);\n  i2s.begin(RATE);\n}\nvoid loop1() {\n  static uint32_t phase = 0; static float lp = 0, wander = 0; static int n = 0;\n  float f = vFreq, u = vUnsettled, lvl = vLevel;\n  if (++n >= 256) { n = 0; wander += 0.08f * noise(); wander *= 0.98f; }     // slow random wander\n  float fe = f * (1.0f + u * 0.012f * wander);\n  phase += (uint32_t)(fe * 4294967296.0f / RATE);\n  float s = sine[phase >> 22] / 32768.0f;\n  lp += 0.15f * (noise() - lp);                                              // softened noise\n  float out = lvl * MAX_DRIVE * ((1.0f - 0.6f * u) * s + 0.6f * u * lp * 2.0f);\n  int16_t v = (int16_t)(constrain(out, -MAX_DRIVE, MAX_DRIVE) * 32767);   // a real ceiling: noise peaks are clipped, never louder\n  i2s.write16(v, v);\n}\n\n// ------------------------------------------------------------ verdicts and envelopes\nenum Mode { IDLE, VERDICT, SWEEP, FINE, HOLD } mode = IDLE;\nuint32_t t0 = 0, lastHeart = 0, toolUntil = 0, pulseEnd[2] = {0, 0};\nbool heartResting = false, working = false;\nfloat sweepF = F_LO, fineCenter = 0;\n\nvoid pulse(int which) {                 // one count on a mechanical counter\n  int pin = which == 0 ? P_TASKS : P_UNSET;\n  digitalWrite(pin, HIGH); pulseEnd[which] = millis() + 120;\n}\n\nvoid verdict(int settled) {\n  if (saved.f0 <= 0) return;             // no figure chosen yet: do nothing rather than guess\n  vFreq = saved.f0; vUnsettled = constrain((100 - settled) / 100.0f, 0.0f, 1.0f);\n  mode = VERDICT; t0 = millis();\n  saved.verdicts++; storeSaved();\n  pulse(0); if (settled < saved.thresh) pulse(1);\n}\n\nfloat verdictLevel(uint32_t ms) {        // 0.4 s up, 3.5 s hold, 0.3 s down; then the brass rings down by itself\n  if (ms < 400) return ms / 400.0f;\n  if (ms < 3900) return 1.0f;\n  if (ms < 4200) return 1.0f - (ms - 3900) / 300.0f;\n  return -1;\n}\n\n// ------------------------------------------------------------ one-way wire\nString line;\nvoid handle(const String& s) {\n  if (s.length() == 0) return;\n  char c = s[0]; int v = s.substring(1).toInt();\n  if (c == 'V') verdict(constrain(v, 0, 100));\n  else if (c == 'W') working = (v == 1);\n  else if (c == 'T') toolUntil = millis() + 1500;\n  else if (c == 'H') { lastHeart = millis(); heartResting = (v == 0); }\n}\n\n// ------------------------------------------------------------ setup by hand: USB, with the tray open\nvoid usbCommand(String s) {\n  s.trim();\n  if (s.startsWith(\"f \")) { vFreq = s.substring(2).toFloat(); vUnsettled = 0; vLevel = 0.7f; mode = HOLD; Serial.println(\"holding\"); }\n  else if (s == \"stop\") { vLevel = 0; mode = IDLE; }\n  else if (s.startsWith(\"save \")) { saved.f0 = s.substring(5).toFloat(); storeSaved(); Serial.println(\"saved\"); }\n  else if (s.startsWith(\"thresh \")) { saved.thresh = s.substring(7).toInt(); storeSaved(); Serial.println(\"saved\"); }\n  else if (s.startsWith(\"test \")) verdict(s.substring(5).toInt());\n  else if (s == \"sweep\") { mode = SWEEP; sweepF = F_LO; t0 = millis(); }\n  else Serial.printf(\"figure %.2f Hz, unsettled below %d, %lu verdicts\\n\", saved.f0, saved.thresh, saved.verdicts);\n}\n\n// ------------------------------------------------------------ the setup button\n// Press once: the plate slowly shows every figure it can make (about 15 minutes).\n// Press when you see the one you like: it searches just around it.\n// Press again at the crispest moment: that is your figure. Hold 3 s at any time to cancel.\nuint32_t btnDown = 0; bool btnWas = false;\nvoid button() {\n  bool down = digitalRead(P_SETUP) == LOW; uint32_t now = millis();\n  if (down && !btnWas) btnDown = now;\n  if (!down && btnWas) {\n    uint32_t held = now - btnDown;\n    if (held > 3000) { mode = IDLE; vLevel = 0; }\n    else if (held > 40) {\n      if (mode == SWEEP) { fineCenter = sweepF; sweepF = fineCenter * 0.985f; mode = FINE; t0 = now; }\n      else if (mode == FINE) { saved.f0 = sweepF; storeSaved(); vLevel = 0; mode = IDLE; delay(800); verdict(100); }\n      else { mode = SWEEP; sweepF = F_LO; t0 = now; }\n    }\n  }\n  btnWas = down;\n}\n\n// ------------------------------------------------------------ lights\nvoid lights() {\n  uint32_t now = millis();\n  bool lightsOn = digitalRead(P_LIGHTS) == HIGH;\n  bool alive = lastHeart && now - lastHeart < 20000;\n  int gap = 0, rake = 0, pilot = 0;\n  if (lightsOn) {\n    if (alive && !heartResting) { gap = 180; rake = 200; }\n    else if (alive) { float b = 0.5f - 0.5f * cosf(2 * PI * (now % 6000) / 6000.0f); gap = 10 + (int)(80 * b); rake = 40; }\n    else { pilot = (now % 10000) < 250 ? 255 : 0; }          // off, but not broken\n  }\n  analogWrite(P_GAP, gap); analogWrite(P_RAKE, rake); analogWrite(P_PILOT, pilot);\n  digitalWrite(P_WORK, alive && working); digitalWrite(P_TOOL, alive && now < toolUntil);\n}\n\nvoid setup() {\n  loadSaved();\n  int outs[] = {P_TASKS, P_UNSET, P_WORK, P_TOOL, P_GAP, P_RAKE, P_PILOT};\n  for (int p : outs) { pinMode(p, OUTPUT); digitalWrite(p, LOW); }\n  pinMode(P_SETUP, INPUT_PULLUP); pinMode(P_LIGHTS, INPUT_PULLUP);\n  analogWriteFreq(20000);\n  Serial.begin(115200);                        // USB: setup by hand only\n  Serial1.setRX(1); Serial1.begin(9600);       // the one-way wire\n}\n\nvoid loop() {\n  uint32_t now = millis();\n  while (Serial1.available()) { char c = Serial1.read(); if (c == '\\n') { handle(line); line = \"\"; } else if (line.length() < 16) line += c; }\n  if (Serial.available()) usbCommand(Serial.readStringUntil('\\n'));\n  for (int i = 0; i < 2; i++) if (pulseEnd[i] && now > pulseEnd[i]) { digitalWrite(i ? P_UNSET : P_TASKS, LOW); pulseEnd[i] = 0; }\n  button();\n  if (mode == VERDICT) { float l = verdictLevel(now - t0); if (l < 0) { vLevel = 0; mode = IDLE; } else vLevel = l; }\n  else if (mode == SWEEP) { vUnsettled = 0; vLevel = 0.7f; vFreq = sweepF; if (now - t0 > 300) { t0 = now; sweepF *= 1.001f; if (sweepF > F_HI) { mode = IDLE; vLevel = 0; } } }\n  else if (mode == FINE)  { vUnsettled = 0; vLevel = 0.7f; vFreq = sweepF; if (now - t0 > 1500) { t0 = now; sweepF *= 1.0005f; if (sweepF > fineCenter * 1.015f) sweepF = fineCenter * 0.985f; } }\n  lights();\n}\n"};
var PLACARD="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"120mm\" height=\"70mm\" viewBox=\"0 0 120 70\">\n<!-- Engrave on brass, 120 x 70 mm. Text only; outline is the cut line. Fonts: convert to outlines before sending. -->\n<rect x=\"0.5\" y=\"0.5\" width=\"119\" height=\"69\" rx=\"3\" fill=\"none\" stroke=\"#000\" stroke-width=\"0.2\"/>\n<g font-family=\"Georgia, serif\" fill=\"#000\">\n<text x=\"8\" y=\"12\" font-size=\"4.2\" font-weight=\"bold\">What you're seeing</text>\n<text x=\"8\" y=\"17.5\" font-size=\"3\">How settled the agent was at its shakiest moment in its last task.</text>\n<text x=\"8\" y=\"21.5\" font-size=\"3\">A crisp figure: settled. A smeared figure: unsettled.</text>\n<text x=\"8\" y=\"32\" font-size=\"4.2\" font-weight=\"bold\">What it can't tell you</text>\n<text x=\"8\" y=\"37.5\" font-size=\"3\">Whether the work was right. Settled is not the same as correct.</text>\n<text x=\"8\" y=\"48\" font-size=\"4.2\" font-weight=\"bold\">Why it can't be faked</text>\n<text x=\"8\" y=\"53.5\" font-size=\"3\">The agent runs on its own computer and never sees this table.</text>\n<text x=\"8\" y=\"57.5\" font-size=\"3\">One wire runs one way, to a controller with no radio.</text>\n</g></svg>";
function cutFiles(){var cm=PSIZE*10,F=[];
  F.push({name:'brass-plate-'+PSIZE+'cm.dxf',data:DXF().rect(0,0,cm,cm).circ(cm/2,cm/2,6.5).bytes()});
  F.push({name:'glass-cover.dxf',data:DXF().rect(0,0,576,576).bytes()});
  F.push({name:'vent-panel.dxf',data:DXF().rect(0,0,500,100).circ(10,10,4.2).circ(490,10,4.2).circ(10,90,4.2).circ(490,90,4.2).bytes()});
  F.push({name:'divider-panel.dxf',data:DXF().rect(0,0,520,128).circ(260,64,20).bytes()});
  F.push({name:'hatch-plate.dxf',data:DXF().rect(0,0,300,150).circ(12,12,5.5).circ(288,12,5.5).circ(12,138,5.5).circ(288,138,5.5).circ(60,75,25).circ(110,75,25).bytes()});
  F.push({name:'placard-optional.svg',data:enc.encode(PLACARD)});
  F.push({name:'ORDER-SHEET.txt',data:enc.encode(['THE SAND TABLE: CUT FILES','All DXF files in millimetres, true size, cut layer only.','',
   'BRASS SHEET, C260 or C360, 1 mm (or the thickness your desk test chose), unlacquered',
   '  brass-plate-'+PSIZE+'cm.dxf  x 1   '+cm+' x '+cm+' mm, 6.5 mm centre hole (match your driver\'s stud). Deburr; keep it flat: no bends, no dents.','',
   'PERFORATED BRASS SHEET, about 0.8-1 mm, round holes about 3 mm, 40-50% open (buy stock perforated sheet, cut to these outlines)',
   '  vent-panel.dxf     x 2   500 x 100 mm, four 4.2 mm screw holes (M4 into the cast inserts)',
   '  divider-panel.dxf  x 1   520 x 128 mm, one 20 mm hole for the single cable between the compartments','',
   'LOW-IRON GLASS, 4 mm, edges polished, corners eased',
   '  glass-cover.dxf    x 1   576 x 576 mm, sits in a 5 mm rebate on felt (most glass shops just need the size)','',
   'BRASS SHEET, 1.5 mm',
   '  hatch-plate.dxf    x 1   300 x 150 mm: four 5.5 mm holes (M5 thumbscrews), two 25 mm grommet holes (power cord in, internet cable in)','',
   'OPTIONAL: placard-optional.svg, engraved on a 120 x 70 mm brass plate. Convert text to outlines first.',
   '','Plate size in these files: '+PSIZE+' cm, as set in the model. Set it from your desk-test result before you press the button.'].join('\r\n'))});
  return F;}
function softFiles(){return Object.keys(SW).map(function(k){return{name:k,data:enc.encode(SW[k])};});}
function save(blob,name){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},3000);}
var out=document.getElementById('fileOut');
document.getElementById('mkCut').addEventListener('click',function(){save(zip(cutFiles()),'sandtable-cut-files.zip');out.textContent='Saved sandtable-cut-files.zip: plate ('+PSIZE+' cm), glass, vents, divider, placard and the order sheet.';});
document.getElementById('mkSoft').addEventListener('click',function(){save(zip(softFiles()),'sandtable-software.zip');out.textContent='Saved sandtable-software.zip: the meter, the controller firmware, the setup sheets, and the smaller versions.';});
window.SAND_FILES={cutFiles:cutFiles,softFiles:softFiles,zip:zip};
})();
